/**
 * Runtime decoder + Canvas tracer for the pre-built JMA warning-area topology
 * (`public/geo/jma-class20-topo.json`, generated by `scripts/build-jma-topology.ts`).
 *
 * Key properties:
 * - Every border between two warning areas is stored ONCE as a shared arc. Fills and strokes of both
 *   neighbours trace the very same vertices at every zoom -> no slivers, overlaps or "noise" lines.
 * - Each vertex carries the minimum zoom at which it becomes visible (Visvalingam, topology-safe), so
 *   LOD is selected per zoom step instead of per-polygon greedy decimation.
 * - Borders are classified (coast / prefecture / division / municipality) and stroked as a mesh, so every
 *   line is drawn exactly once (half the work, no double-stroked antialias halos).
 */

/** Integer coordinate resolution: normalized Web Mercator * scale (= world px at zoom 14). */
export const TOPO_COORD_SCALE = 256 * 2 ** 14;
export const TOPO_LEVEL_STEPS_PER_ZOOM = 2;
export const TOPO_MAX_ZOOM = 12;
export const TOPO_LEVEL_CHAR_OFFSET = 48; // '0'

export interface JmaTopoFile {
  v: 1;
  source: string;
  generatedAt: string;
  scale: number;
  minZoom: number;
  stepsPerZoom: number;
  /** Delta-encoded integer [dx0, dy0, dx1, dy1, ...] per arc (first pair absolute). */
  arcs: number[][];
  /** One char per vertex: (char - '0') = LOD level code. */
  levels: string[];
  features: Array<{
    c: string; // class20 code
    n: string; // name
    d: string; // 57-division code
    p: number; // prefecture id
    l: [number, number] | null; // label point [lon, lat]
    a: number[][][]; // polygons -> rings -> arc refs (negative = ~index reversed)
  }>;
}

export type TopoArcKind = 'coast' | 'pref' | 'division' | 'muni';

export interface TopoShape {
  index: number;
  id: string;
  name: string;
  divisionCode: string;
  prefId: number;
  labelPoint: [number, number] | null; // [lat, lon]
  minNormX: number;
  minNormY: number;
  maxNormX: number;
  maxNormY: number;
  /** Ring arc refs (all rings; the source data has no holes). */
  rings: Int32Array[];
  /** Bounding-box span (normalized) per ring for micro-island culling. */
  ringSpans: Float64Array;
}

export interface JmaTopology {
  minZoom: number;
  stepsPerZoom: number;
  maxLevel: number;
  arcCount: number;
  /** Full-resolution normalized coords per arc. */
  arcCoords: Float64Array[];
  /** LOD level code per vertex. */
  arcLevels: Uint8Array[];
  /** [minX, minY, maxX, maxY] * arcCount in normalized units. */
  arcBBox: Float64Array;
  arcKind: TopoArcKind[];
  shapes: TopoShape[];
  shapeById: Map<string, TopoShape>;
  arcsByKind: Record<TopoArcKind, Int32Array>;
  /** Arcs forming the outline of each 57-division (one side inside, the other outside / sea). */
  divisionOutlineArcs: Map<string, Int32Array>;
  /** Arcs strictly inside each division (municipality borders). */
  divisionInnerArcs: Map<string, Int32Array>;
  /** Lazily built + cached LOD arc coordinate arrays. */
  getArcsAtLevel(level: number): Float64Array[];
  levelForZoom(zoom: number): number;
}

export function decodeJmaTopology(file: JmaTopoFile): JmaTopology {
  if (!file || file.v !== 1 || !Array.isArray(file.arcs)) {
    throw new Error('Invalid JMA topology file');
  }
  const scale = file.scale || TOPO_COORD_SCALE;
  const minZoom = file.minZoom ?? 2;
  const stepsPerZoom = file.stepsPerZoom || TOPO_LEVEL_STEPS_PER_ZOOM;
  const arcCount = file.arcs.length;
  const arcCoords: Float64Array[] = new Array(arcCount);
  const arcLevels: Uint8Array[] = new Array(arcCount);
  const arcBBox = new Float64Array(arcCount * 4);
  let maxLevel = 0;

  for (let a = 0; a < arcCount; a++) {
    const src = file.arcs[a];
    const lvStr = file.levels[a] || '';
    const n = src.length >> 1;
    const coords = new Float64Array(n * 2);
    const lv = new Uint8Array(n);
    let x = 0;
    let y = 0;
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (let i = 0; i < n; i++) {
      x += src[2 * i];
      y += src[2 * i + 1];
      const nx = x / scale;
      const ny = y / scale;
      coords[2 * i] = nx;
      coords[2 * i + 1] = ny;
      if (nx < minX) minX = nx;
      if (nx > maxX) maxX = nx;
      if (ny < minY) minY = ny;
      if (ny > maxY) maxY = ny;
      const code = (lvStr.charCodeAt(i) || TOPO_LEVEL_CHAR_OFFSET) - TOPO_LEVEL_CHAR_OFFSET;
      lv[i] = code;
      if (code > maxLevel) maxLevel = code;
    }
    arcCoords[a] = coords;
    arcLevels[a] = lv;
    arcBBox[4 * a] = minX;
    arcBBox[4 * a + 1] = minY;
    arcBBox[4 * a + 2] = maxX;
    arcBBox[4 * a + 3] = maxY;
  }

  // ---- Shapes + arc adjacency ----
  const arcOwnerA = new Int32Array(arcCount).fill(-1);
  const arcOwnerB = new Int32Array(arcCount).fill(-1);
  const shapes: TopoShape[] = [];
  const shapeById = new Map<string, TopoShape>();

  file.features.forEach((f, index) => {
    const rings: Int32Array[] = [];
    const spans: number[] = [];
    let sMinX = Infinity;
    let sMinY = Infinity;
    let sMaxX = -Infinity;
    let sMaxY = -Infinity;
    for (const poly of f.a || []) {
      for (const ring of poly || []) {
        if (!Array.isArray(ring) || ring.length === 0) continue;
        const refs = Int32Array.from(ring);
        let rMinX = Infinity;
        let rMinY = Infinity;
        let rMaxX = -Infinity;
        let rMaxY = -Infinity;
        for (let k = 0; k < refs.length; k++) {
          const ai = refs[k] < 0 ? ~refs[k] : refs[k];
          if (ai < 0 || ai >= arcCount) continue;
          if (arcOwnerA[ai] === -1) arcOwnerA[ai] = index;
          else if (arcOwnerA[ai] !== index && arcOwnerB[ai] === -1) arcOwnerB[ai] = index;
          rMinX = Math.min(rMinX, arcBBox[4 * ai]);
          rMinY = Math.min(rMinY, arcBBox[4 * ai + 1]);
          rMaxX = Math.max(rMaxX, arcBBox[4 * ai + 2]);
          rMaxY = Math.max(rMaxY, arcBBox[4 * ai + 3]);
        }
        rings.push(refs);
        spans.push(Math.max(rMaxX - rMinX, rMaxY - rMinY));
        sMinX = Math.min(sMinX, rMinX);
        sMinY = Math.min(sMinY, rMinY);
        sMaxX = Math.max(sMaxX, rMaxX);
        sMaxY = Math.max(sMaxY, rMaxY);
      }
    }
    // Sort rings by size (largest first) so tiny islets can be culled with an early `continue`
    const order = spans.map((_, i) => i).sort((i, j) => spans[j] - spans[i]);
    const shape: TopoShape = {
      index,
      id: f.c,
      name: f.n,
      divisionCode: f.d,
      prefId: f.p,
      labelPoint: f.l ? [f.l[1], f.l[0]] : null,
      minNormX: sMinX,
      minNormY: sMinY,
      maxNormX: sMaxX,
      maxNormY: sMaxY,
      rings: order.map((i) => rings[i]),
      ringSpans: Float64Array.from(order.map((i) => spans[i])),
    };
    shapes.push(shape);
    if (f.c) shapeById.set(f.c, shape);
  });

  // ---- Classify arcs ----
  const arcKind: TopoArcKind[] = new Array(arcCount);
  const kindLists: Record<TopoArcKind, number[]> = {
    coast: [],
    pref: [],
    division: [],
    muni: [],
  };
  const outline = new Map<string, number[]>();
  const inner = new Map<string, number[]>();
  const pushTo = (m: Map<string, number[]>, k: string, v: number) => {
    if (!k) return;
    let l = m.get(k);
    if (!l) {
      l = [];
      m.set(k, l);
    }
    l.push(v);
  };
  for (let a = 0; a < arcCount; a++) {
    const sa = arcOwnerA[a] >= 0 ? shapes[arcOwnerA[a]] : null;
    const sb = arcOwnerB[a] >= 0 ? shapes[arcOwnerB[a]] : null;
    let kind: TopoArcKind;
    if (!sa || !sb) kind = 'coast';
    else if (sa.prefId !== sb.prefId) kind = 'pref';
    else if (sa.divisionCode !== sb.divisionCode) kind = 'division';
    else kind = 'muni';
    arcKind[a] = kind;
    kindLists[kind].push(a);
    if (kind === 'muni') {
      pushTo(inner, sa!.divisionCode, a);
    } else {
      if (sa) pushTo(outline, sa.divisionCode, a);
      if (sb && sb.divisionCode !== sa?.divisionCode) pushTo(outline, sb.divisionCode, a);
    }
  }
  const toI32 = (m: Map<string, number[]>) => {
    const r = new Map<string, Int32Array>();
    for (const [k, v] of m) r.set(k, Int32Array.from(v));
    return r;
  };

  // ---- LOD cache ----
  const lodCache = new Map<number, Float64Array[]>();
  const getArcsAtLevel = (level: number): Float64Array[] => {
    const lvl = Math.max(0, Math.min(maxLevel, Math.floor(level)));
    if (lvl >= maxLevel) return arcCoords;
    const cached = lodCache.get(lvl);
    if (cached) return cached;
    const out: Float64Array[] = new Array(arcCount);
    for (let a = 0; a < arcCount; a++) {
      const lv = arcLevels[a];
      const src = arcCoords[a];
      let cnt = 0;
      for (let i = 0; i < lv.length; i++) if (lv[i] <= lvl) cnt++;
      if (cnt === lv.length) {
        out[a] = src;
        continue;
      }
      const dst = new Float64Array(cnt * 2);
      let p = 0;
      for (let i = 0; i < lv.length; i++) {
        if (lv[i] <= lvl) {
          dst[p++] = src[2 * i];
          dst[p++] = src[2 * i + 1];
        }
      }
      out[a] = dst;
    }
    lodCache.set(lvl, out);
    return out;
  };

  const levelForZoom = (zoom: number): number =>
    Math.max(
      0,
      Math.min(maxLevel, Math.floor((zoom - minZoom) * stepsPerZoom))
    );

  return {
    minZoom,
    stepsPerZoom,
    maxLevel,
    arcCount,
    arcCoords,
    arcLevels,
    arcBBox,
    arcKind,
    shapes,
    shapeById,
    arcsByKind: {
      coast: Int32Array.from(kindLists.coast),
      pref: Int32Array.from(kindLists.pref),
      division: Int32Array.from(kindLists.division),
      muni: Int32Array.from(kindLists.muni),
    },
    divisionOutlineArcs: toI32(outline),
    divisionInnerArcs: toI32(inner),
    getArcsAtLevel,
    levelForZoom,
  };
}

/** Minimal subset of CanvasRenderingContext2D used by the tracers (keeps this module DOM-free/testable). */
export interface PathSink {
  moveTo(x: number, y: number): void;
  lineTo(x: number, y: number): void;
  closePath(): void;
}

export interface TopoViewport {
  worldScale: number;
  originX: number;
  originY: number;
  minNormX: number;
  minNormY: number;
  maxNormX: number;
  maxNormY: number;
  /** Rings / closed arcs smaller than this (normalized span) are skipped. */
  minSpanNorm: number;
  wrapOffsetNormX?: number;
}

export function isTopoShapeVisible(sh: TopoShape, vp: TopoViewport): boolean {
  const w = vp.wrapOffsetNormX || 0;
  return !(
    sh.maxNormX + w < vp.minNormX ||
    sh.minNormX + w > vp.maxNormX ||
    sh.maxNormY < vp.minNormY ||
    sh.minNormY > vp.maxNormY
  );
}

/** Appends closed sub-paths for every ring of `shape` (shared arcs -> seamless with neighbours). */
export function traceTopoShape(
  ctx: PathSink,
  shape: TopoShape,
  arcs: Float64Array[],
  vp: TopoViewport
): number {
  const s = vp.worldScale;
  const ox = vp.originX - (vp.wrapOffsetNormX || 0) * s;
  const oy = vp.originY;
  let pts = 0;
  for (let r = 0; r < shape.rings.length; r++) {
    if (r > 0 && shape.ringSpans[r] < vp.minSpanNorm) break; // rings sorted by span desc
    const refs = shape.rings[r];
    let started = false;
    for (let k = 0; k < refs.length; k++) {
      const ref = refs[k];
      const reversed = ref < 0;
      const c = arcs[reversed ? ~ref : ref];
      if (!c) continue;
      const n = c.length >> 1;
      if (!reversed) {
        for (let i = started ? 1 : 0; i < n; i++) {
          const x = c[2 * i] * s - ox;
          const y = c[2 * i + 1] * s - oy;
          if (!started) {
            ctx.moveTo(x, y);
            started = true;
          } else ctx.lineTo(x, y);
        }
      } else {
        for (let i = started ? n - 2 : n - 1; i >= 0; i--) {
          const x = c[2 * i] * s - ox;
          const y = c[2 * i + 1] * s - oy;
          if (!started) {
            ctx.moveTo(x, y);
            started = true;
          } else ctx.lineTo(x, y);
        }
      }
      pts += n;
    }
    if (started) ctx.closePath();
  }
  return pts;
}

/** Appends open polylines for the given arcs (each border drawn exactly once). */
export function traceTopoArcs(
  ctx: PathSink,
  topo: JmaTopology,
  arcIdx: Int32Array,
  arcs: Float64Array[],
  vp: TopoViewport
): number {
  const s = vp.worldScale;
  const ox = vp.originX - (vp.wrapOffsetNormX || 0) * s;
  const oy = vp.originY;
  const bb = topo.arcBBox;
  const w = vp.wrapOffsetNormX || 0;
  let drawn = 0;
  for (let k = 0; k < arcIdx.length; k++) {
    const a = arcIdx[k];
    const minX = bb[4 * a] + w;
    const minY = bb[4 * a + 1];
    const maxX = bb[4 * a + 2] + w;
    const maxY = bb[4 * a + 3];
    if (maxX < vp.minNormX || minX > vp.maxNormX || maxY < vp.minNormY || minY > vp.maxNormY) {
      continue;
    }
    if (maxX - minX < vp.minSpanNorm && maxY - minY < vp.minSpanNorm) continue;
    const c = arcs[a];
    const n = c.length >> 1;
    if (n < 2) continue;
    ctx.moveTo(c[0] * s - ox, c[1] * s - oy);
    for (let i = 1; i < n; i++) {
      ctx.lineTo(c[2 * i] * s - ox, c[2 * i + 1] * s - oy);
    }
    drawn++;
  }
  return drawn;
}

/**
 * Rebuilds a lon/lat GeoJSON FeatureCollection (full resolution) from the topology so legacy consumers
 * (point-in-polygon city intensity lookup, label points) keep working without the 10 raw JMA downloads.
 */
export function topologyToGeoJson(topo: JmaTopology): any {
  const toLonLat = (nx: number, ny: number): [number, number] => {
    const lon = (nx - 0.5) * 360;
    const e = Math.exp((0.5 - ny) * 4 * Math.PI);
    const lat = (Math.asin((e - 1) / (e + 1)) * 180) / Math.PI;
    return [Math.round(lon * 1e5) / 1e5, Math.round(lat * 1e5) / 1e5];
  };
  const features = topo.shapes.map((sh) => {
    const polygons = sh.rings.map((refs) => {
      const ring: [number, number][] = [];
      for (let k = 0; k < refs.length; k++) {
        const ref = refs[k];
        const rev = ref < 0;
        const c = topo.arcCoords[rev ? ~ref : ref];
        const n = c.length >> 1;
        if (!rev) {
          for (let i = ring.length ? 1 : 0; i < n; i++) ring.push(toLonLat(c[2 * i], c[2 * i + 1]));
        } else {
          for (let i = ring.length ? n - 2 : n - 1; i >= 0; i--) ring.push(toLonLat(c[2 * i], c[2 * i + 1]));
        }
      }
      if (ring.length > 0) {
        const f = ring[0];
        const l = ring[ring.length - 1];
        if (f[0] !== l[0] || f[1] !== l[1]) ring.push([f[0], f[1]]);
      }
      return [ring];
    });
    return {
      type: 'Feature',
      properties: {
        code: sh.id,
        name: sh.name,
        divisionCode: sh.divisionCode,
        prefId: sh.prefId,
        labelPoints: sh.labelPoint ? [[sh.labelPoint[1], sh.labelPoint[0]]] : [],
      },
      geometry: { type: 'MultiPolygon', coordinates: polygons },
    };
  });
  return { type: 'FeatureCollection', features };
}
